// Web Essentials – zelftesten van Canvas als meerkeuzekaarten (oefening: true = blauwe kaart "Oefening").
// Ze komen achter de laatste kaart van hetzelfde onderwerp in het hoofdstuk (zoals de oefenkaarten).
// v = vraag met de keuzes a) tot d), a = juiste keuze, o = onderwerp, uitleg = welke zelftest + waarom

const kaarten_WEB_zelftest = {
  "1 – Introductie & HTML-basis": [
    { v: "Wat zijn de 'Drie Pijlers van het Web' en welke specifieke rol vervult HTML daarin?\na) HTML (Vormgeving), CSS (Database), JavaScript (Netwerk)\nb) HTML (Structuur & Inhoud), CSS (Vormgeving & Layout), JavaScript (Gedrag & Interactiviteit)\nc) HTML (Interactiviteit), CSS (Serverlogica), JavaScript (Tekst)\nd) HTML (Animaties), CSS (SEO), JavaScript (Structuur)", a: "b) HTML (Structuur & Inhoud), CSS (Vormgeving & Layout), JavaScript (Gedrag & Interactiviteit)", o: "2.2 Drie pijlers van het web", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 1. HTML zorgt voor de structuur en inhoud, CSS voor de vormgeving en layout, JavaScript voor gedrag en interactiviteit." },
    { v: "Wat is het hoofddoel van de declaratie <!DOCTYPE html> helemaal bovenaan een HTML-document?\na) Het laadt automatisch een extern CSS-stylesheet in.\nb) Het geeft aan de browser door dat het een HTML5-document betreft en voorkomt 'quirks mode' in browsers.\nc) Het stelt de taal van de pagina in op Nederlands.\nd) Het versleutelt de HTML-code voor zoekmachines.", a: "b) Het geeft aan de browser door dat het een HTML5-document betreft en voorkomt 'quirks mode' in browsers.", o: "4. Boilerplate", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 2. <!DOCTYPE html> zegt de browser dat het om HTML5 gaat, zodat hij niet in 'quirks mode' gaat." },
    { v: "Welke tag binnen het <head>-element is essentieel om de tekencodering in te stellen op UTF-8, zodat speciale tekens en accenten correct getoond worden?\na) <meta charset=\"UTF-8\">\nb) <link encoding=\"UTF-8\">\nc) <script type=\"UTF-8\">\nd) <style utf=\"8\">", a: "a) <meta charset=\"UTF-8\">", o: "4.1 Onderdelen van de head", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 3. <meta charset=\"UTF-8\"> staat in de head en zorgt dat accenten en speciale tekens juist getoond worden." },
    { v: "Waar wordt de inhoud van het <title>-element in een HTML-document standaard weergegeven?\na) Als een grote titel bovenaan de inhoud op de webpagina zelf.\nb) In de titelbalk of op het tabblad van de browser, en als titel in zoekresultaten van Google.\nc) Enkel in de broncode van de pagina; het is nergens zichtbaar voor bezoekers.\nd) In de voettekst (footer) van het document.", a: "b) In de titelbalk of op het tabblad van de browser, en als titel in zoekresultaten van Google.", o: "4.1 Onderdelen van de head", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 4. De title verschijnt op het tabblad (of de titelbalk) van de browser en als titel in de zoekresultaten." },
    { v: "Wat is de aanbevolen best practice met betrekking tot het aantal <h1>-elementen op één HTML-pagina?\na) Je mag op elke pagina maximum 6 <h1>-tags plaatsen.\nb) Elke paragraaf moet voorzien zijn van een eigen <h1>-tag.\nc) Gebruik slechts één <h1> per pagina, die de hoofdtitel van het gehele document vertegenwoordigt.\nd) <h1> mag alleen gebruikt worden binnen een <blockquote>.", a: "c) Gebruik slechts één <h1> per pagina, die de hoofdtitel van het gehele document vertegenwoordigt.", o: "5.1 Headings (koppen)", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 5. Eén h1 per pagina: de hoofdtitel van het hele document." },
    { v: "Wat is het semantische verschil tussen het <strong>-element en het <b>-element?\na) <strong> maakt tekst schuin, terwijl <b> tekst onderstreept.\nb) <strong> heeft een semantische betekenis (sterke nadruk/belangrijkheid voor screenreaders), terwijl <b> puur visueel vetgedrukt is zonder extra inhoudelijke betekenis.\nc) <b> is een blok-element en <strong> is een inline-element.\nd) Er is geen enkel verschil; beide zijn in HTML5 afgeschaft.", a: "b) <strong> heeft een semantische betekenis (sterke nadruk/belangrijkheid voor screenreaders), terwijl <b> puur visueel vetgedrukt is zonder extra inhoudelijke betekenis.", o: "5.3 Visuele vs. semantische opmaak", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 6. strong = belangrijk (semantisch, screenreaders leggen nadruk). b = enkel visueel vet." },
    { v: "Welk van de onderstaande HTML-elementen is een voorbeeld van een leeg element (void element) zonder sluitingstag?\na) <p>\nb) <br>\nc) <article>\nd) <div>", a: "b) <br>", o: "3.2 Elementen, tags en attributen", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 7. br is een leeg (void) element: geen inhoud en geen sluitingstag." },
    { v: "Welke stelling over blok-elementen (block-level) en inline-elementen is JUIST?\na) Blok-elementen beginnen op een nieuwe regel en nemen standaard de volledige beschikbare breedte in; inline-elementen blijven op dezelfde regel staan en nemen alleen de ruimte van hun inhoud in.\nb) Inline-elementen beginnen steeds op een nieuwe regel en mogen alle blok-elementen omsluiten.\nc) Voorbeelden van blok-elementen zijn <span>, <a> en <em>.\nd) Voorbeelden van inline-elementen zijn <div>, <p> en <section>.", a: "a) Blok-elementen beginnen op een nieuwe regel en nemen standaard de volledige beschikbare breedte in; inline-elementen blijven op dezelfde regel staan en nemen alleen de ruimte van hun inhoud in.", o: "3.3 Regels bij het nesten", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 8. Blok-elementen starten op een nieuwe regel en nemen de volle breedte. Inline-elementen blijven op dezelfde regel en nemen enkel de ruimte van hun inhoud." },
    { v: "Welke van de onderstaande voorbeelden van het nesten van HTML-elementen is FOUT volgens de HTML-structuurregels?\na) Een <a> (hyperlink) die een <strong> bevat.\nb) Een <p> (paragraaf) waarin een <ol> (geordende lijst) is genest.\nc) Een <section> die een <h2> en twee <p>-elementen bevat.\nd) Een <ul> die drie <li>-elementen bevat.", a: "b) Een <p> (paragraaf) waarin een <ol> (geordende lijst) is genest.", o: "3.3 Regels bij het nesten", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 9. Een p mag geen blok-elementen bevatten, dus ook geen ol." },
    { v: "Welke combinatie van elementen wordt best gebruikt om een semantische definitielijst (Definition List) op te bouwen?\na) <ul>, <ol> en <li>\nb) <dl>, <dt> en <dd>\nc) <list>, <term> en <def>\nd) <list>, <definition> en <description>", a: "b) <dl>, <dt> en <dd>", o: "7.3 Definitielijst (dl)", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 10. dl = de lijst, dt = de term, dd = de beschrijving." },
    { v: "Stel dat een HTML-bestand in een submap staat en je wilt linken naar een afbeelding in de bovenliggende map. Welke relatieve URL-notatie gebruik je om één map hoger te navigeren?\na) href=\"./afbeelding.jpg\"\nb) href=\"../afbeelding.jpg\"\nc) href=\"../../afbeelding.jpg\"\nd) href=\"top/afbeelding.jpg\"", a: "b) href=\"../afbeelding.jpg\"", o: "8.3 Mappenstructuur & relatieve URL's", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 11. ../ = één map hoger. ./ = de huidige map." },
    { v: "Welke character entity moet in HTML gebruikt worden om het teken '<' (kleiner dan) veilig als gewone tekst op het scherm af te beelden zonder dat de browser het als de start van een tag ziet?\na) &lt;\nb) &gt;\nc) &amp;\nd) &copy;", a: "a) &lt;", o: "9. Character entities", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 12. &lt; = less than (<). &gt; = greater than (>)." },
    { v: "Wat is het semantische verschil tussen een <article> en een <section> in HTML5?\na) <article> wordt gebruikt voor navigatiemenu's; <section> voor voetteksten.\nb) <article> vertegenwoordigt een zelfstandige, herbruikbare eenheid inhoud (zoals een blogpost, nieuwsbericht of productkaart); <section> is een algemenere thematische groepering van inhoud.\nc) <section> is een inline-element; <article> is een leeg element.\nd) Er is geen verschil; beide elementen zijn synoniemen voor <div>.", a: "b) <article> vertegenwoordigt een zelfstandige, herbruikbare eenheid inhoud (zoals een blogpost, nieuwsbericht of productkaart); <section> is een algemenere thematische groepering van inhoud.", o: "10.1 Semantische layout-elementen", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 13. article = zelfstandige inhoud die op zichzelf kan bestaan. section = een thematische groep inhoud." },
    { v: "Wat is de juiste manier om een subscript (bijv. H2O) en superscript (bijv. E=mc²) te noteren?\na) H<sub>2</sub>O en E=mc<sup>2</sup>\nb) H<sup>2</sup>O en E=mc<sub>2</sub>\nc) H<subscript>2</subscript>O en E=mc<super>2</super>\nd) H<down>2</down>O en E=mc<up>2</up>", a: "a) H<sub>2</sub>O en E=mc<sup>2</sup>", o: "5.3 Visuele vs. semantische opmaak", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 14. sub = subscript (lager), sup = superscript (hoger)." },
    { v: "Welke code is juist om een hyperlink te maken die opent in een nieuw tabblad?\na) <a href=\"https://voorbeeld.nl\" target=\"_blank\">Bezoek onze site</a>\nb) <a url=\"https://voorbeeld.nl\" open=\"new\">Bezoek onze site</a>\nc) <a link=\"https://voorbeeld.nl\" target=\"new\">Bezoek onze site</a>\nd) <a href=\"https://voorbeeld.nl\" window=\"blank\">Bezoek onze site</a>", a: "a) <a href=\"https://voorbeeld.nl\" target=\"_blank\">Bezoek onze site</a>", o: "8.1 Externe en interne links", oefening: true,
      uitleg: "Zelftest theorie 1, vraag 15. href geeft het adres, target=\"_blank\" opent de link in een nieuw tabblad." },
  ],
  "2 – HTML media, tabellen & formulieren": [
    { v: "Welk attribuut is op het <img>-element absoluut verplicht voor webtoegankelijkheid (a11y) en SEO, en wat moet je invullen als de afbeelding puur decoratief is?\na) Het title-attribuut is verplicht; bij een decoratieve afbeelding vul je title=\"decoratie\" in.\nb) Het alt-attribuut is verplicht; bij een decoratieve afbeelding laat je het alt-attribuut leeg (alt=\"\").\nc) Het src-attribuut is verplicht; een decoratieve afbeelding heeft geen alt-attribuut nodig en dit mag je weglaten.\nd) Het role-attribuut is verplicht; bij een decoratieve afbeelding gebruik je role=\"none\".", a: "b) Het alt-attribuut is verplicht; bij een decoratieve afbeelding laat je het alt-attribuut leeg (alt=\"\").", o: "1.2 Het attribuut alt, accessibility & SEO", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 1. alt is verplicht. Bij een puur decoratieve afbeelding: alt=\"\" (leeg), zodat een screenreader ze overslaat." },
    { v: "Waarom is het een best practice om altijd de intrinsieke attributen width en height op te geven in de HTML-tag van een <img>, zelfs als je de afbeelding later met CSS schaalt?\na) Omdat de browser de afbeelding anders niet kan downloaden.\nb) Om te voorkomen dat de afbeelding vervormt op mobiele apparaten.\nc) Zodat de browser direct de juiste ruimte op de pagina reserveert, wat Cumulative Layout Shift (CLS) voorkomt.\nd) Om het bestandsformaat automatisch te converteren naar WebP.", a: "c) Zodat de browser direct de juiste ruimte op de pagina reserveert, wat Cumulative Layout Shift (CLS) voorkomt.", o: "1.1 Basissyntaxis & attributen van img", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 2. Met width en height reserveert de browser meteen de juiste ruimte: geen Cumulative Layout Shift (CLS)." },
    { v: "Wat is de functie van het attribuut loading=\"lazy\" op een <img>- of <iframe>-element?\na) Het laadt een afbeelding in lage resolutie die langzaam scherper wordt.\nb) Het stelt het inladen uit totdat het element bijna in de zichtbare viewport van de gebruiker komt, wat de initiële laadtijd verbetert.\nc) Het comprimeert de afbeelding automatisch voor langzame internetverbindingen.\nd) Het laadt de afbeelding pas nadat de gebruiker erop heeft geklikt.", a: "b) Het stelt het inladen uit totdat het element bijna in de zichtbare viewport van de gebruiker komt, wat de initiële laadtijd verbetert.", o: "1.1 Basissyntaxis & attributen van img", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 3. loading=\"lazy\" laadt pas als het element bijna in beeld komt: snellere eerste laadtijd." },
    { v: "Welke HTML5-elementencombinatie gebruik je volgens de semantische richtlijnen wanneer een afbeelding een zelfstandige eenheid vormt die voorzien moet worden van een bijschrift?\na) <div class=\"image\"> met <span class=\"caption\">\nb) <picture> met <label>\nc) <figure> met <figcaption>\nd) <section> met <summary>", a: "c) <figure> met <figcaption>", o: "1.4 figure en figcaption", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 4. figure = de zelfstandige eenheid, figcaption = het bijschrift." },
    { v: "Hoe kun je het <picture>-element gebruiken voor formaat-fallbacks (bijv. moderne WebP/AVIF formaten aanbieden met een JPG fallback)?\na) Door het type-attribuut te gebruiken op het <img>-element.\nb) Door meerdere <source>-elementen te plaatsen met het type-attribuut (bijv. type=\"image/avif\") vóór de standaard <img>.\nc) Door het attribuut format=\"webp,jpg\" in te stellen op de <picture>-tag.\nd) Dit is niet mogelijk in HTML; dit moet via JavaScript geregeld worden.", a: "b) Door meerdere <source>-elementen te plaatsen met het type-attribuut (bijv. type=\"image/avif\") vóór de standaard <img>.", o: "1.3 Afbeeldingsformaten op het web", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 5. In picture zet je source-elementen met een type (bv. image/avif, image/webp) vóór de gewone img, die dient als fallback." },
    { v: "Wat is het grote voordeel van een inline geplaatste SVG (<svg>…</svg> direct in de HTML) ten opzichte van een gekoppelde SVG via <img src=\"logo.svg\">?\na) Een inline SVG laadt sneller op mobiele telefoons.\nb) Inline SVG maakt geen gebruik van XML.\nc) Het SVG-element wordt onderdeel van de DOM, waardoor je individuele paden en kleuren kunt stijlen met CSS (bijv. fill: red; bij :hover).\nd) Een inline SVG vereist geen alt-attribuut.", a: "c) Het SVG-element wordt onderdeel van de DOM, waardoor je individuele paden en kleuren kunt stijlen met CSS (bijv. fill: red; bij :hover).", o: "1.7 SVG insluiten", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 6. Een inline SVG wordt deel van de DOM, dus je kan paden en kleuren stijlen met CSS (bv. fill bij :hover)." },
    { v: "Gegeven dit audio-fragment:\n  <audio controls preload=\"metadata\">\n    <source src=\"media/podcast.mp3\" type=\"audio/mpeg\">\n    <source src=\"media/podcast.ogg\" type=\"audio/ogg\">\n    <p>Uw browser ondersteunt geen HTML5 audio.</p>\n  </audio>\nWat is de functie van de paragraaf <p> binnen het <audio>-element?\na) Deze tekst wordt getoond als ondertiteling tijdens het afspelen.\nb) Dit is een beschrijvend bijschrift voor schermlezers.\nc) Dit is fallback-inhoud die enkel getoond wordt in hele oude browsers die het <audio>-element niet ondersteunen.\nd) Deze tekst verschijnt wanneer het audiobestand niet gevonden kan worden op de server.", a: "c) Dit is fallback-inhoud die enkel getoond wordt in hele oude browsers die het <audio>-element niet ondersteunen.", o: "2.1 HTML5 audio", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 7. Tekst binnen audio is fallback: enkel zichtbaar in oude browsers die audio niet kennen." },
    { v: "Wat gebeurt er als je het attribuut autoplay toevoegt aan een <video>-element zonder het attribuut muted toe te voegen (bijv. <video autoplay controls>)?\na) De video speelt direct af op maximaal volume.\nb) De browser negeert het autoplay-attribuut en blokkeert het automatisch afspelen om de gebruiker niet te storen.\nc) De pagina geeft een kritieke HTML-foutmelding en stopt met laden.\nd) autoplay is geen geldig attribuut bij video, dat mag je dus niet gebruiken.", a: "b) De browser negeert het autoplay-attribuut en blokkeert het automatisch afspelen om de gebruiker niet te storen.", o: "2.2 HTML5 video", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 8. Browsers blokkeren autoplay met geluid. Autoplay werkt enkel samen met muted." },
    { v: "Welk attribuut op het <video>-element gebruik je om een voorbeeld-afbeelding (thumbnail) te tonen voordat de video gestart wordt?\na) src\nb) preview\nc) poster\nd) thumbnail", a: "c) poster", o: "2.2 HTML5 video", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 9. poster = de afbeelding die je ziet voor de video start." },
    { v: "Waarvoor dient het attribuut playsinline op een HTML5 <video>-element?\na) Het zorgt ervoor dat de video in een lus (loop) blijft afspelen.\nb) Het voorkomt dat de video op mobiele apparaten automatisch naar volledig scherm (fullscreen) schakelt bij het afspelen.\nc) Het verbergt de bedieningsknoppen van de video.\nd) Het laadt de video in een inline frame (<iframe>).", a: "b) Het voorkomt dat de video op mobiele apparaten automatisch naar volledig scherm (fullscreen) schakelt bij het afspelen.", o: "2.2 HTML5 video", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 10. playsinline: op mobiel speelt de video af in de pagina en niet automatisch fullscreen." },
    { v: "Waarom is het toevoegen van een title-attribuut verplicht/essentieel bij het insluiten van externe content via een <iframe> (zoals een Google Map of YouTube video)?\na) Om de titel boven de iframe af te drukken op de pagina.\nb) Zodat zoekmachines de iframe kunnen indexeren als een gewone pagina.\nc) Voor toegankelijkheid (a11y), zodat schermlezers aan visueel beperkte gebruikers kunnen voorlezen welke inhoud er in het frame geladen is.\nd) Om te voorkomen dat het iframe blokkeert door een CORS-fout.", a: "c) Voor toegankelijkheid (a11y), zodat schermlezers aan visueel beperkte gebruikers kunnen voorlezen welke inhoud er in het frame geladen is.", o: "2.3 Externe content met iframe", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 11. Het title-attribuut laat een screenreader voorlezen wat er in het frame staat." },
    { v: "Wat is het verschil tussen afbeeldingsformaten van het type 'Raster' (zoals JPEG, PNG, WebP) en 'Vector' (zoals SVG)?\na) Rasterafbeeldingen bestaan uit pixels en verliezen kwaliteit bij vergroten; vectorafbeeldingen bestaan uit wiskundige formules en zijn oneindig schaalbaar zonder kwaliteitsverlies.\nb) Rasterafbeeldingen worden enkel gebruikt voor video; vectorafbeeldingen voor tekst.\nc) Vectorafbeeldingen ondersteunen geen transparantie; rasterafbeeldingen wel.\nd) Rasterafbeeldingen hebben altijd een kleinere bestandsgrootte dan SVG-bestanden.", a: "a) Rasterafbeeldingen bestaan uit pixels en verliezen kwaliteit bij vergroten; vectorafbeeldingen bestaan uit wiskundige formules en zijn oneindig schaalbaar zonder kwaliteitsverlies.", o: "1.3 Afbeeldingsformaten op het web", oefening: true,
      uitleg: "Zelftest HTML Media, vraag 12. Raster = pixels, wordt wazig bij vergroten. Vector (SVG) = wiskundige vormen, oneindig schaalbaar." },
    { v: "Wat is volgens de les de absolute 'gouden regel' voor het gebruik van HTML-tabellen (<table>) op moderne webpagina's?\na) Tabellen moeten altijd gebruikt worden om de pagina-layout op te bouwen.\nb) Tabellen worden uitsluitend gebruikt voor gestructureerde, tabulaire data en NOOIT voor pagina-layout.\nc) Tabellen mogen enkel gebruikt worden als er meer dan 10 rijen gegevens zijn.\nd) Tabellen moeten verplicht gecombineerd worden met JavaScript om zichtbaar te zijn.", a: "b) Tabellen worden uitsluitend gebruikt voor gestructureerde, tabulaire data en NOOIT voor pagina-layout.", o: "3. Gouden regel voor tabellen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 1. Tabellen enkel voor tabulaire data, nooit voor de layout van een pagina." },
    { v: "Welk HTML-element vormt het buitenste omhullende element van een tabel?\na) <grid>\nb) <table>\nc) <tabular>\nd) <t-container>", a: "b) <table>", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 2. table is het buitenste element van de tabel." },
    { v: "Welke van de volgende elementen mogen direct als kind binnen een <table> geplaatst worden?\na) Enkel <td> en <p>\nb) <tr>, <thead>, <tbody>, <tfoot>, <caption> en <colgroup>\nc) <div>, <span> en <section>\nd) Enkel <th> en <td>", a: "b) <tr>, <thead>, <tbody>, <tfoot>, <caption> en <colgroup>", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 3. Rechtstreeks in table: caption, colgroup, thead, tbody, tfoot en tr. td staat altijd in een tr." },
    { v: "Welke tag gebruikt men in HTML om een nieuwe rij binnen een tabel aan te maken?\na) <row>\nb) <trow>\nc) <tr>\nd) <table-row>", a: "c) <tr>", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 4. tr = table row." },
    { v: "Wat is het fundamentele verschil tussen een <th>-element en een <td>-element?\na) <th> bevat tabelkoppen (header data) en <td> bevat gewone gegevens (table data).\nb) <th> is voor tekst en <td> is uitsluitend voor getallen.\nc) <th> kan niet gestijld worden met CSS, <td> wel.\nd) <th> mag enkel in de eerste rij van een tabel gebruikt worden.", a: "a) <th> bevat tabelkoppen (header data) en <td> bevat gewone gegevens (table data).", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 5. th = table header (kop), td = table data (gegevens)." },
    { v: "Hoe geeft een browser de inhoud van een <th>-element standaard weer in vergelijking met een <td>-element?\na) Cursief en rechts uitgelijnd.\nb) Vetgedrukt en gecentreerd.\nc) Onderlijnd en links uitgelijnd.\nd) Met een rode achtergrondkleur.", a: "b) Vetgedrukt en gecentreerd.", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 6. th is standaard vetgedrukt en gecentreerd." },
    { v: "Waar moet het <caption>-element geplaatst worden binnen de HTML-code van een tabel?\na) Helemaal onderaan, net voor de </table> sluitingstag.\nb) Direct als allereerste kind na de <table> openingstag.\nc) Binnenin het <thead>-element.\nd) Buiten de tabel in een <p>-element.", a: "b) Direct als allereerste kind na de <table> openingstag.", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 7. caption komt meteen na de openingstag <table>." },
    { v: "Wat is het doel van het <caption>-element bij een HTML-tabel?\na) Het definieert de kolombreedtes van de tabel.\nb) Het dient als een titel of bijschrift dat de tabel beschrijft voor lezers en schermlezers.\nc) Het maakt van de tabel een sorteerbare interactieve lijst.\nd) Het voegt een rand toe rondom de tabel.", a: "b) Het dient als een titel of bijschrift dat de tabel beschrijft voor lezers en schermlezers.", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 8. caption = titel of bijschrift van de tabel, ook voor screenreaders." },
    { v: "Welke tag wordt gebruikt om de koptekst/kolomkoppen van een tabel semantisch te groeperen?\na) <header>\nb) <table-header>\nc) <thead>\nd) <top-row>", a: "c) <thead>", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 9. thead groepeert de kopregel(s)." },
    { v: "Welke tag groepeert de daadwerkelijke inhoud/gegevensrijen van een tabel?\na) <tbody>\nb) <main-data>\nc) <tcontent>\nd) <data-rows>", a: "a) <tbody>", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 10. tbody groepeert de rijen met gegevens." },
    { v: "Waarvoor dient het <tfoot>-element in een HTML-tabel?\na) Om bronvermeldingen of voetnoten buiten de tabel te plaatsen.\nb) Om een samenvattende rij (zoals totalen, gemiddelden of eindconclusies) te groeperen.\nc) Om de onderste rand van de tabel visueel dikker te maken.\nd) Om pagina-navigatie toe te voegen onder de tabel.", a: "b) Om een samenvattende rij (zoals totalen, gemiddelden of eindconclusies) te groeperen.", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 11. tfoot groepeert een samenvattende rij, zoals totalen." },
    { v: "Wat is de meest logische en standaard volgorde van de semantische secties binnen een <table>?\na) <tbody> → <thead> → <tfoot>\nb) <caption> → <thead> → <tbody> → <tfoot>\nc) <tfoot> → <caption> → <thead> → <tbody>\nd) <thead> → <tfoot> → <caption> → <tbody>", a: "b) <caption> → <thead> → <tbody> → <tfoot>", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 12. caption, dan thead, dan tbody, dan tfoot." },
    { v: "Waarvoor wordt het attribuut scope=\"col\" gebruikt op een <th>-element?\na) Om aan te geven dat de koptekst geldt voor alle cellen in die specifieke kolom.\nb) Om de kolom een specifieke achtergrondkleur te geven.\nc) Om meerdere kolommen samen te voegen tot één cel.\nd) Om de kolom te verbergen op mobiele schermen.", a: "a) Om aan te geven dat de koptekst geldt voor alle cellen in die specifieke kolom.", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 13. scope=\"col\": de kop geldt voor de hele kolom." },
    { v: "Wanneer gebruik je het attribuut scope=\"row\" op een <th>-element?\na) Wanneer de <th> de kop is voor alle cellen in die specifieke horizontale rij.\nb) Wanneer je een nieuwe rij wilt toevoegen aan het <tbody>.\nc) Wanneer de cel precies 2 rijen hoog moet zijn.\nd) Wanneer je de tekst in de rij verticaal wilt uitlijnen.", a: "a) Wanneer de <th> de kop is voor alle cellen in die specifieke horizontale rij.", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 14. scope=\"row\": de kop geldt voor de hele rij." },
    { v: "Waarom is het toevoegen van het scope-attribuut op <th>-elementen zo belangrijk voor webtoegankelijkheid (accessibility)?\na) Zonder scope kunnen zoekmachines de tabel niet indexeren.\nb) Het stelt schermlezers in staat om bij het navigeren door datacellen de bijbehorende kolom- of rijkop voor te lezen.\nc) Het zorgt ervoor dat de tabel automatisch een rand krijgt in CSS.\nd) Het maakt het mogelijk om cellen met de muis te verslepen.", a: "b) Het stelt schermlezers in staat om bij het navigeren door datacellen de bijbehorende kolom- of rijkop voor te lezen.", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 15. Met scope kan een screenreader bij elke cel de juiste kolom- of rijkop voorlezen." },
    { v: "Wat doet het attribuut colspan=\"3\" op een <td>- of <th>-element?\na) Het maakt de cel drie keer zo hoog.\nb) Het laat de cel de breedte van 3 kolommen beslaan (samenvoegen over 3 kolommen).\nc) Het maakt 3 kopieën van de cel aan.\nd) Het stelt de lettergrootte van de cel in op 3rem.", a: "b) Het laat de cel de breedte van 3 kolommen beslaan (samenvoegen over 3 kolommen).", o: "3.2 Cellen samenvoegen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 16. colspan=\"3\": de cel is 3 kolommen breed." },
    { v: "Wat doet het attribuut rowspan=\"2\" op een <td>-element?\na) Het voegt 2 lege rijen toe onder de huidige rij.\nb) Het laat de cel verticaal uitstrekken over 2 opeenvolgende rijen.\nc) Het verdeelt de rij in 2 gelijke helften.\nd) Het centreert de tekst over 2 regels.", a: "b) Het laat de cel verticaal uitstrekken over 2 opeenvolgende rijen.", o: "3.2 Cellen samenvoegen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 17. rowspan=\"2\": de cel loopt over 2 rijen." },
    { v: "Stel dat een tabel normaal 4 kolommen heeft. In de eerste rij heeft de eerste <td> het attribuut colspan=\"2\". Hoeveel <td>-elementen moeten er nog in die eerste rij staan om exact 4 kolommen te vullen?\na) 1\nb) 2\nc) 3\nd) 4", a: "b) 2", o: "3.2 Cellen samenvoegen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 18. De cel met colspan=\"2\" vult al 2 kolommen. 4 - 2 = nog 2 td's." },
    { v: "Als in Rij 1 de eerste cel een rowspan=\"2\" heeft in een tabel van 3 kolommen, hoeveel cellen moet Rij 2 dan bevatten om niet uit te steken?\na) 1 cel\nb) 2 cellen\nc) 3 cellen\nd) 4 cellen", a: "b) 2 cellen", o: "3.2 Cellen samenvoegen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 19. De cel met rowspan=\"2\" vult in rij 2 al de eerste kolom. 3 - 1 = nog 2 cellen." },
    { v: "Mag je binnen een <td>-element andere HTML-elementen plaatsen, zoals afbeeldingen (<img>), paragrafen (<p>) of zelfs een complete <form>?\na) Nee, een <td> mag uitsluitend platte tekst bevatten.\nb) Ja, een <td> is een container waarin vrijwel alle HTML-elementen geplaatst mogen worden.\nc) Enkel <span> en <strong> zijn toegestaan.\nd) Alleen als er een colspan attribuut aanwezig is.", a: "b) Ja, een <td> is een container waarin vrijwel alle HTML-elementen geplaatst mogen worden.", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 20. Een td is een container: er mag bijna alles in, zoals img, p of zelfs een form." },
    { v: "Wat is er fout aan deze HTML-code?\n  <table>\n    <td>Product</td>\n    <td>Prijs</td>\n  </table>\na) De <td>-elementen staan niet binnen een <tr> (tabelrij).\nb) Het attribuut border ontbreekt.\nc) <td> moet vervangen worden door <p>.\nd) Een tabel moet altijd minimaal 10 cellen bevatten.", a: "a) De <td>-elementen staan niet binnen een <tr> (tabelrij).", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 21. td's moeten altijd in een tr staan." },
    { v: "Waarvoor dienen de elementen <colgroup> en <col> in een HTML-tabel?\na) Om rijen samen te voegen.\nb) Om een hele kolom of groep kolommen in één keer van attributen of styling (zoals breedte of achtergrond) te voorzien.\nc) Om tabeldata om te zetten naar een grafiek.\nd) Om de tabel op te splitsen in meerdere losse tabellen.", a: "b) Om een hele kolom of groep kolommen in één keer van attributen of styling (zoals breedte of achtergrond) te voorzien.", o: "3.5 colgroup en col", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 22. Met colgroup en col geef je een hele kolom (of groep kolommen) in één keer een stijl, zoals breedte of achtergrond." },
    { v: "Hoe moeten visuele eigenschappen van een tabel (zoals randen, cel-padding en achtergrondkleuren) volgens de moderne webstandaarden ingesteld worden?\na) Met verouderde HTML-attributen zoals border=\"1\", cellpadding=\"5\" en bgcolor=\"red\".\nb) Via CSS-stijlregels (zoals border-collapse, padding en background-color).\nc) Rechtstreeks in het <caption>-element.\nd) Dat kan niet, tabellen hebben een vaste lay-out die niet aangepast kan worden.", a: "b) Via CSS-stijlregels (zoals border-collapse, padding en background-color).", o: "3. Gouden regel voor tabellen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 23. Randen, padding en achtergrondkleuren doe je met CSS, niet met oude attributen zoals border of bgcolor." },
    { v: "Welke CSS-eigenschap zorgt ervoor dat de dubbele randen tussen tabelcellen samensmelten tot één enkele strakke rand?\na) border-spacing: 0;\nb) border-collapse: collapse;\nc) table-border: single;\nd) border-style: merge;", a: "b) border-collapse: collapse;", o: "3. Gouden regel voor tabellen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 24. border-collapse: collapse; laat de dubbele randen samensmelten tot één rand. (Uitgelegd in les 4.)" },
    { v: "Is het toegestaan om meerdere <tbody>-elementen te gebruiken binnen één enkele <table>?\na) Nee, een tabel mag absoluut maar één <tbody> bevatten.\nb) Ja, meerdere <tbody>-elementen zijn toegestaan om grote tabellen in logische datablokken onder te verdelen.\nc) Ja, maar alleen als er geen <thead> aanwezig is.\nd) Alleen in combinatie met <tfoot>.", a: "b) Ja, meerdere <tbody>-elementen zijn toegestaan om grote tabellen in logische datablokken onder te verdelen.", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 25. Meerdere tbody's mogen: zo verdeel je een grote tabel in logische blokken." },
    { v: "Welke tag gebruik je voor een cel die de titel van een kolom bevat?\na) <td>\nb) <th scope=\"col\">\nc) <caption>\nd) <thead-data>", a: "b) <th scope=\"col\">", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 26. Een kolomtitel is een kopcel: <th scope=\"col\">." },
    { v: "Wat betekent colspan=\"0\" in de officiële HTML-specificatie (hoewel niet door alle browsers even goed ondersteund)?\na) De cel wordt verborgen.\nb) De cel strekt zich uit tot de allereerste kolom van de tabel.\nc) De cel strekt zich uit over alle resterende kolommen van de kolomgroep waarin hij zich bevindt.\nd) Het geeft een foutmelding in het HTML-document.", a: "c) De cel strekt zich uit over alle resterende kolommen van de kolomgroep waarin hij zich bevindt.", o: "3.2 Cellen samenvoegen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 27. colspan=\"0\" = over alle resterende kolommen van de kolomgroep (niet in elke browser even goed)." },
    { v: "Waarom wordt het vanuit het oogpunt van toegankelijkheid afgeraden om kopcellen (<th>) helemaal leeg te laten?\na) Omdat de tabel dan niet meer kan geladen worden door de browser.\nb) Omdat schermlezers in de war raken bij het koppelen van de datacellen aan hun respectievelijke kop.\nc) Omdat lege <th>-elementen automatisch rood gekleurd worden.\nd) Omdat CSS geen stijl kan toepassen op lege tags.", a: "b) Omdat schermlezers in de war raken bij het koppelen van de datacellen aan hun respectievelijke kop.", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 28. Een lege th verwart screenreaders bij het koppelen van de cellen aan hun kop." },
    { v: "Wat is de aanbevolen techniek in HTML/CSS om te voorkomen dat een brede tabel op een klein mobiel scherm de pagina-layout sloopt?\na) De tabel verbergen op mobiel met display: none.\nb) De tabel wikkelen in een <div> met CSS-eigenschap overflow-x: auto; om een horizontale scrollbar toe te voegen.\nc) Alle <td> elementen omzetten naar <p> met JavaScript.\nd) Gebruik maken van colspan=\"100%\" op alle cellen.", a: "b) De tabel wikkelen in een <div> met CSS-eigenschap overflow-x: auto; om een horizontale scrollbar toe te voegen.", o: "3. Gouden regel voor tabellen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 29. Zet de tabel in een div met overflow-x: auto; dan krijg je een horizontale scrollbalk. (Uitgelegd in les 4.)" },
    { v: "Welke van de volgende tags mag DIRECT binnenin een <tr> geplaatst worden?\na) <p>\nb) <td> of <th>\nc) <div>\nd) <tbody>", a: "b) <td> of <th>", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 30. In een tr staan enkel td's en th's." },
    { v: "Hoe is de tekst binnen een <td>-element standaard horizontaal uitgelijnd in de meeste browsers?\na) Gecentreerd (center)\nb) Links uitgelijnd (left)\nc) Rechts uitgelijnd (right)\nd) Uitgevuld (justify)", a: "b) Links uitgelijnd (left)", o: "3.1 Basiselementen van een tabel", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 31. td is standaard links uitgelijnd (th gecentreerd)." },
    { v: "Stel dat je een uurrooster maakt met dagen in de kolommen en uren in de rijen. Welke scope attributen gebruik je voor de dagen en de uren?\na) scope=\"row\" voor de dagen, scope=\"col\" voor de uren.\nb) scope=\"col\" voor de dagen (kolomkoppen), scope=\"row\" voor de uren (rijkoppen).\nc) scope=\"group\" voor alles.\nd) Geen scope, dat is enkel voor cijfers.", a: "b) scope=\"col\" voor de dagen (kolomkoppen), scope=\"row\" voor de uren (rijkoppen).", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 32. Dagen staan bovenaan de kolommen: scope=\"col\". Uren staan vooraan de rijen: scope=\"row\"." },
    { v: "Welke van de onderstaande uitspraken over het <tfoot>-element is JUIST?\na) <tfoot> mag enkel tekst bevatten, geen <tr> of <td>.\nb) <tfoot> moet altijd <tr>-elementen bevatten waarin de afsluitende gegevens/totalen staan.\nc) <tfoot> wordt automatisch onderaan de webpagina geplaatst, buiten de tabel.\nd) <tfoot> is verplicht in elke HTML-tabel.", a: "b) <tfoot> moet altijd <tr>-elementen bevatten waarin de afsluitende gegevens/totalen staan.", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 33. Ook tfoot bevat tr's met td's (bv. de totalen)." },
    { v: "Welke van de volgende HTML-fragmenten is een 100% correct opgebouwde tabelrij met kolomkoppen?\na) <tr><th scope=\"col\">Naam</th><th scope=\"col\">Leeftijd</th></tr>\nb) <thead><td>Naam</td><td>Leeftijd</td></thead>\nc) <table><th>Naam</th><th>Leeftijd</th></table>\nd) <tr scope=\"col\"><td>Naam</td><td>Leeftijd</td></tr>", a: "a) <tr><th scope=\"col\">Naam</th><th scope=\"col\">Leeftijd</th></tr>", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 34. th's horen in een tr, met scope=\"col\" voor kolomkoppen." },
    { v: "Een tabel heeft 5 kolommen. Rij 1 heeft 1 cel met colspan=\"3\". Hoeveel gewone cellen (zonder colspan) moeten er nog in Rij 1 staan om de tabel strak uit te lijnen?\na) 1 cel\nb) 2 cellen\nc) 3 cellen\nd) 4 cellen", a: "b) 2 cellen", o: "3.2 Cellen samenvoegen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 35. De cel met colspan=\"3\" vult al 3 kolommen. 5 - 3 = nog 2 cellen." },
    { v: "HTML5 staat het attribuut border=\"1\" op een <table> soms nog toe om snel randen te testen. Wat is echter de aanbevolen manier in modern webdesign?\na) Altijd border=\"1\" blijven gebruiken.\nb) Het border-attribuut weglaten en de randen instellen via CSS (bijv. border: 1px solid black;).\nc) Gebruik maken van het attribuut outline=\"1\".\nd) Randen toevoegen via het <caption>-element.", a: "b) Het border-attribuut weglaten en de randen instellen via CSS (bijv. border: 1px solid black;).", o: "3. Gouden regel voor tabellen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 36. Randen stel je in met CSS, bv. border: 1px solid black;" },
    { v: "Wat wordt er precies bedoeld met de term 'tabulaire data'?\na) Alle tekst die op een webpagina staat.\nb) Gegevens die een duidelijke twee-dimensionale relatie hebben (rijen en kolommen), zoals een prijslijst of roosters.\nc) Een verzameling van hyperlinks en afbeeldingen.\nd) Invoervelden van een formulier.", a: "b) Gegevens die een duidelijke twee-dimensionale relatie hebben (rijen en kolommen), zoals een prijslijst of roosters.", o: "3. Gouden regel voor tabellen", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 37. Tabulaire data = gegevens in rijen en kolommen, zoals een prijslijst of een rooster." },
    { v: "Welke waarde kan het scope attribuut aannemen als een <th> van toepassing is op een hele groep van kolommen?\na) scope=\"cols\"\nb) scope=\"colgroup\"\nc) scope=\"all-cols\"\nd) scope=\"multi-col\"", a: "b) scope=\"colgroup\"", o: "3.4 Tabel-toegankelijkheid (scope)", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 38. scope=\"colgroup\": de kop geldt voor een groep kolommen." },
    { v: "Is het gebruik van <thead>, <tbody> en <tfoot> verplicht voor élke eenvoudige tabel van 2 bij 2 cellen?\na) Ja, zonder deze tags weigert de browser de tabel te tonen.\nb) Nee, voor hele eenvoudige tabellen mag je <tr> direct in <table> plaatsen, maar voor grotere of toegankelijke tabellen is de semantische indeling sterk aanbevolen.\nc) Ja, want anders werkt het scope-attribuut niet.\nd) Nee, <tbody> is verboden in HTML5.", a: "b) Nee, voor hele eenvoudige tabellen mag je <tr> direct in <table> plaatsen, maar voor grotere of toegankelijke tabellen is de semantische indeling sterk aanbevolen.", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 39. Niet verplicht voor een kleine tabel, wel sterk aangeraden voor grotere of toegankelijke tabellen." },
    { v: "Welke combinatie van elementen vormt de meest complete en semantisch correcte HTML5-tabelstructuur?\na) <table> → <caption> → <thead>(<tr><th>) → <tbody>(<tr><td>) → <tfoot>(<tr><td>)\nb) <table> → <tr> → <div> → <p>\nc) <grid> → <header> → <body> → <footer>\nd) <table> → <td> → <tr> → <th>", a: "a) <table> → <caption> → <thead>(<tr><th>) → <tbody>(<tr><td>) → <tfoot>(<tr><td>)", o: "3.3 thead, tbody, tfoot", oefening: true,
      uitleg: "Zelftest HTML Tabellen, vraag 40. table met caption, thead (tr + th), tbody (tr + td) en tfoot (tr + td)." },
    { v: "Welk HTML-element vormt de hoofdcontainer om een interactief formulier op een webpagina te maken waarin gebruikersinvoer verzameld kan worden?\na) <input>\nb) <form>\nc) <fieldset>\nd) <section>", a: "b) <form>", o: "4.2 Het form-element", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 1. form is de container van het hele formulier." },
    { v: "Wat is de functie van het action-attribuut op het <form>-element?\na) Het bepaalt welke JavaScript-functie wordt uitgevoerd bij het laden van de pagina.\nb) Het geeft het URL-adres op van het server-script waar de formuliergegevens naartoe gestuurd moeten worden.\nc) Het bepaalt of het formulier zichtbaar of verborgen is.\nd) Het stelt het type verzendknop in.", a: "b) Het geeft het URL-adres op van het server-script waar de formuliergegevens naartoe gestuurd moeten worden.", o: "4.2 Het form-element", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 2. action = het adres van het script op de server dat de gegevens ontvangt." },
    { v: "Wat gebeurt er wanneer de methode method=\"GET\" wordt gebruikt bij het verzenden van een formulier?\na) De formuliergegevens worden onzichtbaar in de HTTP-request body verzonden.\nb) De formuliergegevens worden als naam=waarde-paren achteraan de URL geplakt in de adresbalk (query string).\nc) De formuliergegevens worden automatisch geëncrypteerd.\nd) Het formulier wordt direct gewist zonder verzending.", a: "b) De formuliergegevens worden als naam=waarde-paren achteraan de URL geplakt in de adresbalk (query string).", o: "4.2 Het form-element", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 3. GET plakt de gegevens als naam=waarde achter de URL (query string)." },
    { v: "Waarom mag de HTTP-methode GET absoluut NIET gebruikt worden bij formulieren waarin wachtwoorden of gevoelige gegevens worden ingevoerd?\na) Omdat GET geen tekstvelden ondersteunt.\nb) Omdat de gegevens zichtbaar in de URL verschijnen, worden opgeslagen in de browsergeschiedenis en in serverlogs terechtkomen.\nc) Omdat GET formulieren beperkt tot maximaal 2 invoervelden.\nd) Omdat GET alleen werkt op mobiele apparaten.", a: "b) Omdat de gegevens zichtbaar in de URL verschijnen, worden opgeslagen in de browsergeschiedenis en in serverlogs terechtkomen.", o: "4.2 Het form-element", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 4. Met GET staan de gegevens zichtbaar in de URL, in de browsergeschiedenis en in de serverlogs." },
    { v: "Welke methode stelt de formuliergegevens onzichtbaar voor de eindgebruiker via de HTTP-request body naar de server?\na) method=\"GET\"\nb) method=\"POST\"\nc) method=\"PUT\"\nd) method=\"SEND\"", a: "b) method=\"POST\"", o: "4.2 Het form-element", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 5. POST stuurt de gegevens onzichtbaar mee in de body van het verzoek." },
    { v: "Wat is het absolute gevolg als een <input>-veld WEL een id heeft, maar GEEN name-attribuut?\na) Het invoerveld is niet zichtbaar op de pagina.\nb) De waarde van het veld wordt NIET meegestuurd bij het verzenden van het formulier naar de server.\nc) De browser geeft een fatale HTML-foutmelding.\nd) Het veld accepteert geen tekst.", a: "b) De waarde van het veld wordt NIET meegestuurd bij het verzenden van het formulier naar de server.", o: "4.1 Werking van een formulier", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 6. Zonder name wordt de waarde niet meegestuurd: de browser stuurt naam=waarde-paren." },
    { v: "Welk HTML-element wordt gebruikt om een toegankelijk tekstlabel te koppelen aan een formulierveld?\na) <text>\nb) <caption>\nc) <label>\nd) <legend>", a: "c) <label>", o: "4.3 Labels & toegankelijkheid", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 7. label koppelt een tekst aan een veld." },
    { v: "Hoe koppel je een expliciet <label> correct aan een specifiek <input>-element?\na) Door het name-attribuut van het label gelijk te maken aan het name-attribuut van het input-veld.\nb) Door het for-attribuut van het label exact gelijk te maken aan het id-attribuut van het input-veld.\nc) Door het class-attribuut van beide elementen gelijk te stellen.\nd) Door het src-attribuut van het label naar het input-veld te laten verwijzen.", a: "b) Door het for-attribuut van het label exact gelijk te maken aan het id-attribuut van het input-veld.", o: "4.3 Labels & toegankelijkheid", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 8. Expliciet: for van het label = id van het input-veld." },
    { v: "Wat is een impliciete koppeling tussen een <label> en een <input>?\na) Het koppelen via een JavaScript-eventlistener.\nb) Het rechtstreeks nesten van het <input>-element IN het <label>-element.\nc) Het weglaten van het <label>-element en alleen een placeholder gebruiken.\nd) Het gebruik van het data-label attribuut.", a: "b) Het rechtstreeks nesten van het <input>-element IN het <label>-element.", o: "4.3 Labels & toegankelijkheid", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 9. Impliciet: het input-veld staat in het label." },
    { v: "Wat is de standaardwaarde van het type-attribuut op een <input>-element als er geen type wordt opgegeven (<input>)?\na) type=\"hidden\"\nb) type=\"button\"\nc) type=\"text\"\nd) type=\"submit\"", a: "c) type=\"text\"", o: "4.5 Tekstinvoer & wachtwoorden", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 10. Zonder type is een input een gewoon tekstveld: type=\"text\"." },
    { v: "Welk type input-element (<input type=\"…\">) moet gebruikt worden voor wachtwoorden zodat ingevoerde tekens visueel gemaskerd worden (bijv. bolletjes of sterretjes)?\na) type=\"hidden\"\nb) type=\"secret\"\nc) type=\"password\"\nd) type=\"private\"", a: "c) type=\"password\"", o: "4.5 Tekstinvoer & wachtwoorden", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 11. type=\"password\" toont bolletjes of sterretjes." },
    { v: "Wat is het visuele en functionele verschil tussen <input type=\"radio\"> en <input type=\"checkbox\">?\na) Radiobuttons zijn vierkant en laten meerdere keuzes toe; checkboxes zijn rond en laten één keuze toe.\nb) Radiobuttons (rond) laten slechts ÉÉN selectie toe binnen een groep; checkboxes (vierkant) laten NUL, ÉÉN of MEERDERE selecties toe.\nc) Radiobuttons werken alleen met getallen; checkboxes alleen met tekst.\nd) Er is geen functioneel verschil, alleen een esthetisch verschil.", a: "b) Radiobuttons (rond) laten slechts ÉÉN selectie toe binnen een groep; checkboxes (vierkant) laten NUL, ÉÉN of MEERDERE selecties toe.", o: "4.6 Radio buttons & checkboxes", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 12. Radio (rond): één keuze per groep. Checkbox (vierkant): nul, één of meer keuzes." },
    { v: "Hoe zorg je ervoor dat een verzameling van drie <input type=\"radio\"> elementen als ÉÉN onderling exclusieve groep werkt?\na) Geef alle drie de radiobuttons exact hetzelfde id-attribuut.\nb) Geef alle drie de radiobuttons exact hetzelfde name-attribuut.\nc) Geef alle drie de radiobuttons hetzelfde class-attribuut.\nd) Plaats de radiobuttons in een <select>-element.", a: "b) Geef alle drie de radiobuttons exact hetzelfde name-attribuut.", o: "4.6 Radio buttons & checkboxes", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 13. Dezelfde name maakt van de radio buttons één groep." },
    { v: "Welk attribuut gebruik je op een <input type=\"checkbox\"> of <input type=\"radio\"> om deze bij het laden van de pagina standaard vooraf aan te vinken?\na) selected\nb) active\nc) checked\nd) default", a: "c) checked", o: "4.6 Radio buttons & checkboxes", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 14. checked vinkt een radio button of checkbox vooraf aan." },
    { v: "Welk HTML-element gebruik je om een keuzemenu (dropdownlijst) te maken?\na) <dropdown>\nb) <datalist>\nc) <select>\nd) <list>", a: "c) <select>", o: "4.7 select, option en optgroup", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 15. select maakt een keuzemenu." },
    { v: "Welk element definieert de afzonderlijke keuzemogelijkheden binnen een <select>-element?\na) <item>\nb) <option>\nc) <choice>\nd) <list-item>", a: "b) <option>", o: "4.7 select, option en optgroup", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 16. Elke keuze is een option." },
    { v: "Hoe koppel je opties binnen een <select>-menu logisch in categorieën of subgroepen?\na) <group>\nb) <optgroup label=\"Groepsnaam\">\nc) <fieldset label=\"Groepsnaam\">\nd) <category>", a: "b) <optgroup label=\"Groepsnaam\">", o: "4.7 select, option en optgroup", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 17. optgroup met label groepeert opties onder een naam." },
    { v: "Welk attribuut plaats je op een specifieke <option> binnen een <select> om die optie standaard geselecteerd te laten zijn?\na) checked\nb) default\nc) selected\nd) primary", a: "c) selected", o: "4.7 select, option en optgroup", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 18. selected kiest een option vooraf. (checked is voor radio en checkbox.)" },
    { v: "Welk element is specifiek ontworpen voor het invoeren van meerdere regels tekst (zoals een opmerking of bericht)?\na) <input type=\"multiline\">\nb) <textarea>\nc) <textbox>\nd) <input type=\"text\" rows=\"5\">", a: "b) <textarea>", o: "4.5 Tekstinvoer & wachtwoorden", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 19. textarea is voor tekst over meerdere regels." },
    { v: "Hoe geef je standaard/initiële tekst mee aan een <textarea>-element?\na) Via het attribuut value=\"Initiële tekst\"\nb) Door de tekst TUSSEN de openingstag <textarea> en sluitingstag </textarea> te plaatsen.\nc) Via het attribuut text=\"Initiële tekst\"\nd) Dit kan uitsluitend via JavaScript.", a: "b) Door de tekst TUSSEN de openingstag <textarea> en sluitingstag </textarea> te plaatsen.", o: "4.5 Tekstinvoer & wachtwoorden", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 20. Bij textarea staat de begintekst tussen <textarea> en </textarea>, niet in value." },
    { v: "Welke twee attributen worden op <textarea> gebruikt om de initiële visuele grootte in aantal rijen en kolommen in te stellen?\na) width en height\nb) rows en cols\nc) lines en chars\nd) size en length", a: "b) rows en cols", o: "4.5 Tekstinvoer & wachtwoorden", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 21. rows = aantal regels, cols = aantal tekens breed." },
    { v: "Welk HTML-element gebruik je om gerelateerde formuliervelden visueel en semantisch te groeperen (meestal weergegeven met een kader eromheen)?\na) <group>\nb) <formgroup>\nc) <fieldset>\nd) <section>", a: "c) <fieldset>", o: "4.4 fieldset en legend", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 22. fieldset groepeert velden, meestal met een kader rond." },
    { v: "Welk element definieert de titel of het opschrift van een <fieldset>?\na) <caption>\nb) <label>\nc) <legend>\nd) <title>", a: "c) <legend>", o: "4.4 fieldset en legend", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 23. legend is de titel van een fieldset." },
    { v: "Wat doet het <datalist>-element in combinatie met een <input>-veld?\na) Het vervangt het formulier door een tabel.\nb) Het toont een lijst met voorgestelde autocompletiewaarden waarin de gebruiker kan zoeken of zelf een vrije waarde kan intypen.\nc) Het blokkeert alle invoer behalve de opgegeven waarden.\nd) Het verstuurt de data automatisch naar een database.", a: "b) Het toont een lijst met voorgestelde autocompletiewaarden waarin de gebruiker kan zoeken of zelf een vrije waarde kan intypen.", o: "4.8 datalist", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 24. datalist geeft suggesties, maar de gebruiker mag ook iets anders typen." },
    { v: "Hoe koppel je een <input>-veld aan een <datalist id=\"steden\">?\na) Met het attribuut datalist=\"steden\" op de input.\nb) Met het attribuut list=\"steden\" op de input.\nc) Met het attribuut for=\"steden\" op de datalist.\nd) Met het attribuut target=\"steden\" op de input.", a: "b) Met het attribuut list=\"steden\" op de input.", o: "4.8 datalist", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 25. list op de input = id van de datalist." },
    { v: "Wat is een belangrijk voordeel van <button type=\"submit\">Verzenden</button> ten opzichte van <input type=\"submit\" value=\"Verzenden\">?\na) <button> werkt zonder JavaScript, <input> niet.\nb) Binnen een <button> kun je HTML-elementen (zoals afbeeldingen, iconen of <strong>-tags) opnemen, terwijl <input> alleen platte tekst als value accepteert.\nc) <button> verstuurt data automatisch via POST.\nd) Er is geen enkel verschil.", a: "b) Binnen een <button> kun je HTML-elementen (zoals afbeeldingen, iconen of <strong>-tags) opnemen, terwijl <input> alleen platte tekst als value accepteert.", o: "4.10 button vs input", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 26. In een button mag HTML staan (bv. een afbeelding of strong). Een input heeft enkel platte tekst in value." },
    { v: "Wat is het standaardgedrag van een <button> binnen een <form> als het type-attribuut NIET expliciet is opgegeven?\na) type=\"button\" (doet niets automatisch)\nb) type=\"reset\" (wist het formulier)\nc) type=\"submit\" (verstuurt het formulier)\nd) type=\"cancel\"", a: "c) type=\"submit\" (verstuurt het formulier)", o: "4.10 button vs input", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 27. Een button in een form zonder type is een submit-knop." },
    { v: "Welk HTML5-attribuut maakt een invoerveld verplicht, waardoor de browser voorkomt dat het formulier verzonden wordt als het veld leeg is?\na) validate\nb) mandatory\nc) required\nd) important", a: "c) required", o: "5.1 Validatie-attributen", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 28. required: het formulier gaat niet weg als het veld leeg is." },
    { v: "Wat is de functie van het title-attribuut wanneer dit gecombineerd wordt met het pattern-attribuut op een <input>-veld?\na) Het verandert het lettertype van de invoer.\nb) De tekst in het title-attribuut wordt door de browser getoond als extra Help-instructie/foutmelding wanneer de invoer niet aan het patroon voldoet.\nc) Het stelt de titel van het formulier in.\nd) Het verbergt het invoerveld voor zoekmachines.", a: "b) De tekst in het title-attribuut wordt door de browser getoond als extra Help-instructie/foutmelding wanneer de invoer niet aan het patroon voldoet.", o: "5.1 Validatie-attributen", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 29. title geeft extra uitleg als de invoer niet aan het pattern voldoet." },
    { v: "Welke attributen gebruik je op <input type=\"number\"> om de minimale en maximale toegestane numerieke waarde te beperken?\na) minimum en maximum\nb) low en high\nc) min en max\nd) start en end", a: "c) min en max", o: "5.1 Validatie-attributen", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 30. min en max beperken de laagste en hoogste waarde." },
    { v: "Waarvoor dient het placeholder-attribuut op een tekstinvoerveld?\na) Het dient als definitieve vervanging van het <label>-element.\nb) Het toont een tijdelijke voorbeeldtekst of hint in het veld die verdwijnt zodra de gebruiker begint te typen.\nc) Het stelt de standaardwaarde in die naar de server gestuurd wordt als het veld leeg blijft.\nd) Het maakt het veld onwijzigbaar.", a: "b) Het toont een tijdelijke voorbeeldtekst of hint in het veld die verdwijnt zodra de gebruiker begint te typen.", o: "5.2 Gebruikersgemak-attributen", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 31. placeholder = een hint in het veld die verdwijnt zodra je typt. Het vervangt geen label." },
    { v: "Wat is het verschil tussen het disabled-attribuut en het readonly-attribuut op een invoerveld?\na) disabled velden worden WEL meegestuurd bij formulierverzending; readonly velden NIET.\nb) disabled velden kunnen niet bewerkt worden en worden NIET meegestuurd naar de server; readonly velden kunnen niet bewerkt worden maar worden WEL meegestuurd.\nc) disabled werkt alleen op buttons; readonly alleen op tekstvakken.\nd) Er is geen enkel verschil tussen deze twee attributen.", a: "b) disabled velden kunnen niet bewerkt worden en worden NIET meegestuurd naar de server; readonly velden kunnen niet bewerkt worden maar worden WEL meegestuurd.", o: "5.2 Gebruikersgemak-attributen", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 32. Beide kan je niet bewerken. disabled wordt niet meegestuurd, readonly wel." },
    { v: "Als je een formulier maakt waarmee gebruikers bestanden (zoals afbeeldingen of PDF's) kunnen uploaden met <input type=\"file\">, welk attribuut is dan verplicht op het <form>-element?\na) method=\"GET\"\nb) enctype=\"multipart/form-data\" (gecombineerd met method=\"POST\")\nc) type=\"upload\"\nd) media=\"file\"", a: "b) enctype=\"multipart/form-data\" (gecombineerd met method=\"POST\")", o: "4.2 Het form-element", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 33. Voor bestanden uploaden: method=\"POST\" en enctype=\"multipart/form-data\"." },
    { v: "Waarvoor dient het <input type=\"hidden\">-element?\na) Om wachtwoorden onzichtbaar in te typen.\nb) Om gegevens op te slaan en mee te sturen naar de server zonder dat deze zichtbaar zijn op de pagina voor de gebruiker (bijv. een gebruikers-ID of sessietoken).\nc) Om foute invoer te verbergen.\nd) Om velden te verbergen voor zoekmachines.", a: "b) Om gegevens op te slaan en mee te sturen naar de server zonder dat deze zichtbaar zijn op de pagina voor de gebruiker (bijv. een gebruikers-ID of sessietoken).", o: "4.9 HTML5 input types", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 34. type=\"hidden\" stuurt een waarde mee die de gebruiker niet ziet (bv. een id)." },
    { v: "Welk HTML5 input-type genereert in ondersteunde browsers een native kleurkiezer (color picker)?\na) type=\"palette\"\nb) type=\"color\"\nc) type=\"rgb\"\nd) type=\"hex\"", a: "b) type=\"color\"", o: "4.9 HTML5 input types", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 35. type=\"color\" geeft een kleurkiezer." },
    { v: "Wat is het effect van het autofocus-attribuut op een invoerveld?\na) Het veld wordt automatisch vergroot wanneer de muis erover beweegt.\nb) De cursor wordt bij het laden van de pagina automatisch in dit specifieke invoerveld geplaatst.\nc) Het veld accepteert alleen cijfers.\nd) Het veld wordt rood als er een fout in staat.", a: "b) De cursor wordt bij het laden van de pagina automatisch in dit specifieke invoerveld geplaatst.", o: "5.2 Gebruikersgemak-attributen", oefening: true,
      uitleg: "Zelftest HTML Formulieren, vraag 36. autofocus zet de cursor bij het laden meteen in dat veld." },
  ],
  "3 – CSS-basis, kleuren & typografie": [
    { v: "Waarvoor staat de afkorting CSS en wat is de primaire functie van CSS in modern webdesign?\na) Creative Style System; het beheren van databases en serverlogica.\nb) Cascading Style Sheets; het verzorgen van de visuele vormgeving en layout, gescheiden van de HTML-structuur.\nc) Computer System Structure; het maken van interactieve animaties met JavaScript.\nd) Centralized Sheet Styling; het opslaan van gebruikersgegevens in de browser.", a: "b) Cascading Style Sheets; het verzorgen van de visuele vormgeving en layout, gescheiden van de HTML-structuur.", o: "1.1 Wat is CSS?", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 1. Cascading Style Sheets: de vormgeving en layout, los van de HTML-structuur." },
    { v: "Welke methode is de absolute 'best practice' voor het toepassen van CSS op een website met meerdere pagina's?\na) Inline CSS via het style-attribuut op elk HTML-element.\nb) Interne CSS via een <style>-tag in de <head> van elke pagina.\nc) Externe CSS via een afzonderlijk .css-bestand dat gekoppeld wordt met een <link>-tag in de <head>.\nd) CSS invoegen via een <script>-tag onderaan de <body>.", a: "c) Externe CSS via een afzonderlijk .css-bestand dat gekoppeld wordt met een <link>-tag in de <head>.", o: "1.2 Drie methoden om CSS toe te passen", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 2. Externe CSS: één .css-bestand, gekoppeld met link in de head van elke pagina." },
    { v: "Wat is een belangrijk voordeel van Interne CSS (<style> in de <head>) ten opzichte van Inline CSS?\na) Interne CSS kan worden hergebruikt op andere HTML-bestanden zonder de code te kopiëren.\nb) Interne CSS scheidt de stijlregels van de individuele HTML-elementen binnen die specifieke pagina.\nc) Interne CSS omzeilt de specifieke regels van de cascade.\nd) Interne CSS laadt sneller dan elk extern CSS-bestand op een netwerk.", a: "b) Interne CSS scheidt de stijlregels van de individuele HTML-elementen binnen die specifieke pagina.", o: "1.2 Drie methoden om CSS toe te passen", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 3. Interne CSS haalt de stijl weg uit de elementen zelf, maar geldt enkel voor die ene pagina." },
    { v: "Wat gebeurt er als je een extern stylesheet koppelt via <link rel=\"stylesheet\" href=\"css/stijl.css\">?\na) De browser downloadt het bestand stijl.css en past de CSS-regels toe op het HTML-document.\nb) Dit is geen correct gebruik van CSS. Dat gaat dus niet werken.\nc) De HTML-pagina wordt geconverteerd naar een PDF-document.\nd) De CSS-regels overschrijven verplicht alle inline HTML-attributen.", a: "a) De browser downloadt het bestand stijl.css en past de CSS-regels toe op het HTML-document.", o: "1.2 Drie methoden om CSS toe te passen", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 4. De browser downloadt stijl.css en past de regels toe." },
    { v: "Uit welke onderdelen bestaat deze CSS-stijlregel?\n  h1 { color: #0056b3; }\na) h1 is de property, color is de selector, #0056b3 is de value.\nb) h1 is de selector, color is de property, #0056b3 is de value; samen vormen ze een declaratie binnen het declaratieblok.\nc) h1 is de class, color is het attribuut, #0056b3 is de variabele.\nd) h1 is het element, color is de waarde, #0056b3 is de eigenschap.", a: "b) h1 is de selector, color is de property, #0056b3 is de value; samen vormen ze een declaratie binnen het declaratieblok.", o: "2.1 CSS-basissyntaxis", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 5. Selector { property: value; }. Property + value = een declaratie, alles tussen { } = het declaratieblok." },
    { v: "Hoe schrijf je een geldige commentaarregel in een CSS-bestand?\na) <!-- Dit is CSS commentaar -->\nb) // Dit is CSS commentaar\nc) /* Dit is CSS commentaar */\nd) # Dit is CSS commentaar", a: "c) /* Dit is CSS commentaar */", o: "2.1 CSS-basissyntaxis", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 6. Commentaar in CSS: /* ... */" },
    { v: "Welke selector selecteert ALLE elementen met de klasse 'highlight' op een pagina?\na) #highlight\nb) .highlight\nc) highlight\nd) *highlight", a: "b) .highlight", o: "2.2 Basisselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 7. Een punt = class-selector." },
    { v: "Wat is een strikte regel omtrent het gebruik van ID-selectors (#id-naam) in HTML en CSS?\na) Een ID mag meerdere keren per pagina gebruikt worden voor verschillende elementen.\nb) Een ID-naam moet uniek zijn en mag slechts één keer per pagina voorkomen.\nc) Een ID mag alleen toegepast worden op <p>-elementen.\nd) Een ID-naam moet verplicht beginnen met een cijfer.", a: "b) Een ID-naam moet uniek zijn en mag slechts één keer per pagina voorkomen.", o: "2.2 Basisselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 8. Een id is uniek: maar één keer per pagina." },
    { v: "Welke CSS-selector selecteert alle <input>-elementen waarvan het type-attribuut exact gelijk is aan 'text'?\na) input.text\nb) input#text\nc) input[type=\"text\"]\nd) input->type(text)", a: "c) input[type=\"text\"]", o: "2.2 Basisselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 9. Attribuutselector: input[type=\"text\"]." },
    { v: "Hoe past de groeperingsselector (komma) stijlen toe in deze CSS-code?\n  h1, h2, .titel { color: navy; }\na) Alleen op een h2 die genest is binnen een h1 met de klasse .titel.\nb) Op alle h1-elementen, alle h2-elementen én alle elementen met de klasse .titel.\nc) Alleen op het eerste h1-element op de pagina.\nd) Op alle elementen behalve h1, h2 en .titel.", a: "b) Op alle h1-elementen, alle h2-elementen én alle elementen met de klasse .titel.", o: "2.4 Elementen groeperen", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 10. De komma groepeert: de regel geldt voor elk van de selectors." },
    { v: "Wat doet de universele selector (*) in CSS?\na) Selecteert uitsluitend alle tekstknoppen op de pagina.\nb) Selecteert alle elementen op de gehele webpagina.\nc) Selecteert alleen het <html>-rootelement.\nd) Selecteert alle elementen die geen class of ID hebben.", a: "b) Selecteert alle elementen op de gehele webpagina.", o: "2.2 Basisselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 11. * selecteert alle elementen." },
    { v: "Welk type combinator wordt hier gebruikt en welke elementen worden geselecteerd?\n  nav a { color: white; }\na) Child selector (>); selecteert alleen <a>-elementen die direct onder <nav> staan.\nb) Descendant selector (spatie); selecteert alle <a>-elementen die zich ergens binnen een <nav> bevinden, ongeacht het nestingsniveau.\nc) Adjacent sibling selector (+); selecteert een <a> die direct na een <nav> staat.\nd) General sibling selector (~); selecteert alle <a>-elementen die na een <nav> staan.", a: "b) Descendant selector (spatie); selecteert alle <a>-elementen die zich ergens binnen een <nav> bevinden, ongeacht het nestingsniveau.", o: "2.3 Combinators & relatieselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 12. Een spatie = descendant: alle a's ergens binnen nav, hoe diep ook." },
    { v: "Gegeven deze HTML:\n  <ul>\n    <li>Item 1</li>\n    <li>\n      <ol>\n        <li>Subitem A</li>\n      </ol>\n    </li>\n  </ul>\nWelke <li>-elementen selecteert de CSS-regel ul > li?\na) Alle <li>-elementen, inclusief 'Subitem A'.\nb) Alleen 'Item 1' en het overkoepelende tweede <li> van de <ul>, maar NIET 'Subitem A' (omdat dat een kind is van <ol>).\nc) Alleen 'Subitem A'.\nd) Geen enkel element omdat <ol> in de weg staat.", a: "b) Alleen 'Item 1' en het overkoepelende tweede <li> van de <ul>, maar NIET 'Subitem A' (omdat dat een kind is van <ol>).", o: "2.3 Combinators & relatieselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 13. > = enkel de directe kinderen. Subitem A is een kind van ol, niet van ul." },
    { v: "Wat is het verschil tussen de adjacent sibling selector (+) en de general sibling selector (~)?\na) + selecteert alle volgende broers/zussen; ~ selecteert alleen de allereerste directe broer/zus die er onmiddellijk op volgt.\nb) + selecteert alleen de allereerste broer/zus die onmiddellijk op het element volgt; ~ selecteert álle volgende broers/zussen op hetzelfde niveau.\nc) + werkt alleen voor klasse-selectors; ~ werkt alleen voor element-selectors.\nd) + selecteert ouders; ~ selecteert kinderen.", a: "b) + selecteert alleen de allereerste broer/zus die onmiddellijk op het element volgt; ~ selecteert álle volgende broers/zussen op hetzelfde niveau.", o: "2.3 Combinators & relatieselectors", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 14. + = enkel de eerste broer/zus meteen erna. ~ = alle volgende broers/zussen." },
    { v: "Wanneer gebruik je een <div> en wanneer een <span> als je elementen wilt groeperen voor CSS-styling?\na) <div> is een inline-element voor korte tekstfragmenten; <span> is een block-level container voor grote secties.\nb) <div> is een block-level container voor het groeperen van meerdere elementen; <span> is een inline-level element voor het stijlen van een specifiek woord of zinsdeel binnen een tekst.\nc) <div> mag alleen in de <head> staan; <span> mag alleen in de <body> staan.\nd) Er is geen enkel verschil; beide zijn identieke HTML5-elementen.", a: "b) <div> is een block-level container voor het groeperen van meerdere elementen; <span> is een inline-level element voor het stijlen van een specifiek woord of zinsdeel binnen een tekst.", o: "2.4 Elementen groeperen", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 15. div = blok-container voor meerdere elementen. span = inline, voor een woord of zinsdeel." },
    { v: "Twee CSS-regels met gelijke specificiteit:\n  p { color: blue; }\n  p { color: red; }\nWelke kleur krijgt de tekst in de paragraaf en waarom?\na) Blauw, omdat de eerste regel altijd voorrang krijgt.\nb) Rood, omdat bij gelijke specificiteit de laatst geschreven regel in de code wint.\nc) Paars, omdat de browser de twee kleuren mengt.\nd) Zwart, omdat er een CSS-conflict ontstaat.", a: "b) Rood, omdat bij gelijke specificiteit de laatst geschreven regel in de code wint.", o: "3.1 De cascade", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 16. Bij gelijke specificiteit wint de regel die het laatst staat." },
    { v: "In welke volgorde worden de 4 kolommen van specificiteit berekend (van hoogste gewicht naar laagste gewicht)?\na) (Type, Class, ID, Inline)\nb) (Inline style, ID, Class/Attribuut/Pseudo-class, Type/Element)\nc) (ID, Inline style, Type, Class)\nd) (Universal, Type, Class, ID)", a: "b) (Inline style, ID, Class/Attribuut/Pseudo-class, Type/Element)", o: "3.2 Specificiteit", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 17. Inline style, dan ID, dan class/attribuut/pseudo-class, dan element." },
    { v: "Wat is de specificiteitsscore van de selector: p.intro-tekst?\na) (0, 0, 0, 1)\nb) (0, 0, 1, 0)\nc) (0, 0, 1, 1)\nd) (0, 1, 0, 1)", a: "c) (0, 0, 1, 1)", o: "3.2 Specificiteit", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 18. 1 class (.intro-tekst) + 1 element (p) = (0, 0, 1, 1)." },
    { v: "Gegeven deze CSS-regels:\n  #hoofd-titel { color: purple; }\n  .titel { color: green; }\n  h1 { color: blue; }\nWelke kleur krijgt <h1 id=\"hoofd-titel\" class=\"titel\">Welkom</h1>?\na) Blauw, omdat h1 een elementselector is.\nb) Groen, omdat .titel een class-selector is.\nc) Paars, omdat een ID-selector (#hoofd-titel) een hogere specificiteitsscore heeft dan class- en elementselectors.\nd) Zwart, de standaardkleur.", a: "c) Paars, omdat een ID-selector (#hoofd-titel) een hogere specificiteitsscore heeft dan class- en elementselectors.", o: "3.2 Specificiteit", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 19. Een ID-selector weegt zwaarder dan een class- of elementselector." },
    { v: "Waarvoor dient !important in CSS en wat is de aanbeveling omtrent het gebruik ervan?\na) Het maakt een regel sneller laadbaar; gebruik het op alle declaraties.\nb) Het geeft een declaratie absolute voorrang boven normale regels; gebruik het zo weinig mogelijk omdat het de cascade verstoort en overschrijven erg moeilijk maakt.\nc) Het maakt een CSS-eigenschap overerfbaar naar alle kinderen; gebruik het bij elke font-declaratie.\nd) Het zet een declaratie om in een CSS-variabele.", a: "b) Het geeft een declaratie absolute voorrang boven normale regels; gebruik het zo weinig mogelijk omdat het de cascade verstoort en overschrijven erg moeilijk maakt.", o: "3.2 Specificiteit", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 20. !important wint van gewone regels. Gebruik het zo weinig mogelijk." },
    { v: "Welke van de volgende CSS-eigenschappen wordt NIET automatisch geërfd door kind-elementen?\na) color\nb) font-family\nc) line-height\nd) border", a: "d) border", o: "3.3 Overerving (inheritance)", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 21. border wordt niet geërfd. color, font-family en line-height wel." },
    { v: "Hoe kun je een kind-element expliciet dwingen om een niet-geërfde eigenschap (of een overschreven eigenschap zoals de tekstkleur van een link) over te nemen van zijn ouder-element?\na) color: default;\nb) color: parent;\nc) color: inherit;\nd) color: auto;", a: "c) color: inherit;", o: "3.3 Overerving (inheritance)", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 22. inherit neemt de waarde van het ouder-element over." },
    { v: "In welke exacte volgorde moeten de link-pseudo-classes geschreven worden in CSS volgens de bekende 'LVHA'-regel?\na) :hover → :active → :visited → :link\nb) :link → :visited → :hover → :active\nc) :active → :hover → :link → :visited\nd) :visited → :link → :active → :hover", a: "b) :link → :visited → :hover → :active", o: "6.1 Link-pseudo-classes (LVHA)", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 23. LVHA: :link, :visited, :hover, :active." },
    { v: "Waarvoor dient de pseudo-class :focus-visible en voor wie is deze essentieel?\na) Om elementen te stijlen wanneer de gebruiker er met de muis over beweegt; essentieel voor mobiele telefoons.\nb) Om een duidelijke visuele indicatie (focus ring) te tonen wanneer een gebruiker via het toetsenbord (TAB-toets) navigeert; essentieel voor webtoegankelijkheid (a11y).\nc) Om spelfouten in formulieren te markeren.\nd) Om te controleren of een afbeelding zichtbaar is op het scherm.", a: "b) Om een duidelijke visuele indicatie (focus ring) te tonen wanneer een gebruiker via het toetsenbord (TAB-toets) navigeert; essentieel voor webtoegankelijkheid (a11y).", o: "6.1 Link-pseudo-classes (LVHA)", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 24. :focus-visible toont een focusrand als je met het toetsenbord (Tab) navigeert: belangrijk voor toegankelijkheid." },
    { v: "Gegeven dit lijstje:\n  <ul>\n    <li>Aap</li>\n    <li>Noot</li>\n    <li>Mies</li>\n  </ul>\nWelk item wordt rood door de CSS-regel li:first-child { color: red; }?\na) Alle drie de items.\nb) Alleen 'Aap' (het eerste kind van de <ul>).\nc) Alleen 'Mies' (het laatste item).\nd) Geen enkel item omdat <li> geen kind kan zijn.", a: "b) Alleen 'Aap' (het eerste kind van de <ul>).", o: "6.2 Structurele pseudo-classes", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 25. :first-child = het eerste kind van de ouder: Aap." },
    { v: "Welke CSS-regel gebruikt een structurele pseudo-class om zebra-strepen (afwisselende achtergrondkleuren) toe te passen op alle even rijen in een tabel?\na) tr:odd { background-color: #f2f2f2; }\nb) tr:nth-child(even) { background-color: #f2f2f2; }\nc) tr.even { background-color: #f2f2f2; }\nd) tr:every(2) { background-color: #f2f2f2; }", a: "b) tr:nth-child(even) { background-color: #f2f2f2; }", o: "6.2 Structurele pseudo-classes", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 26. :nth-child(even) = de even rijen." },
    { v: "Wat selecteert de pseudo-class :last-child in de regel p:last-child?\na) De laatste paragraaf op de hele pagina, ongeacht de ouder.\nb) Een <p>-element, mits dit het allerlaatste kind-element is binnen zijn ouder-element.\nc) Alle paragrafen die na een afbeelding staan.\nd) De laatste letter van elke paragraaf.", a: "b) Een <p>-element, mits dit het allerlaatste kind-element is binnen zijn ouder-element.", o: "6.2 Structurele pseudo-classes", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 27. p:last-child = een p die het laatste kind van zijn ouder is." },
    { v: "Twee externe stylesheets in de <head>:\n  <link rel=\"stylesheet\" href=\"css/base.css\">\n  <link rel=\"stylesheet\" href=\"css/theme.css\">\nIn base.css staat body { color: black; }, in theme.css staat body { color: navy; }, met gelijke specificiteit. Welke kleur krijgt de body?\na) Black, omdat base.css als eerste geladen wordt.\nb) Navy, omdat theme.css als laatste geladen wordt en bij gelijke specificiteit de regels uit het laatst geladen bestand winnen.\nc) Er ontstaat een foutmelding en de tekst wordt wit.\nd) De browser kiest willekeurig een van de twee kleuren.", a: "b) Navy, omdat theme.css als laatste geladen wordt en bij gelijke specificiteit de regels uit het laatst geladen bestand winnen.", o: "3.1 De cascade", oefening: true,
      uitleg: "Zelftest CSS Basis, vraag 28. Gelijke specificiteit: het bestand dat het laatst geladen wordt (theme.css) wint." },
    { v: "Hoeveel standaard Engelse kleurnamen (zoals red, blue, darkcyan) ondersteunt CSS officieel?\na) 16 kleuren\nb) 148 kleuren\nc) 256 kleuren\nd) Onbeperkt", a: "b) 148 kleuren", o: "4.1 Notatiemethoden voor kleuren", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 1. CSS kent 148 Engelse kleurnamen." },
    { v: "Hoe is een hexadecimale kleurcode opgebouwd in CSS (bijv. #FF0000)?\na) Uit 3 getallen tussen 0 en 100 voor Hue, Saturation en Lightness.\nb) Uit een # gevolgd door 6 tekens (0-9 en A-F), waarbij elke 2 tekens respectievelijk Rood, Groen en Blauw vertegenwoordigen (00 t/m FF).\nc) Uit 4 waarden voor Cyan, Magenta, Yellow en Key.\nd) Uit een willekeurige combinatie van letters zonder hekje.", a: "b) Uit een # gevolgd door 6 tekens (0-9 en A-F), waarbij elke 2 tekens respectievelijk Rood, Groen en Blauw vertegenwoordigen (00 t/m FF).", o: "4.1 Notatiemethoden voor kleuren", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 2. # + 6 tekens: 2 voor rood, 2 voor groen, 2 voor blauw (00 tot FF)." },
    { v: "Welke verkorte hexadecimale notatie is exact gelijk aan de kleurcode #FF0000 (puur rood)?\na) #F00\nb) #RED\nc) #FF0\nd) #00F", a: "a) #F00", o: "4.1 Notatiemethoden voor kleuren", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 3. #F00 = #FF0000: elk teken wordt verdubbeld." },
    { v: "Wat is het fundamentele verschil tussen het gebruik van rgba(0, 0, 0, 0.5) op achtergrondkleur en het gebruik van de CSS-property opacity: 0.5?\na) rgba() maakt het hele element inclusief tekst transparant; opacity maakt enkel de achtergrond transparant.\nb) rgba() maakt uitsluitend de kleur/achtergrond transparant waardoor tekst 100% leesbaar blijft; opacity maakt het gehele element inclusief alle tekst en kind-elementen transparant.\nc) Er is geen verschil; beide doen exact hetzelfde.\nd) opacity werkt niet op achtergrondkleuren.", a: "b) rgba() maakt uitsluitend de kleur/achtergrond transparant waardoor tekst 100% leesbaar blijft; opacity maakt het gehele element inclusief alle tekst en kind-elementen transparant.", o: "4.2 Transparantie & alpha", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 4. rgba() maakt enkel die kleur doorzichtig. opacity maakt het hele element doorzichtig, ook de tekst." },
    { v: "Welke waarde heeft het alpha-kanaal in rgba(255, 0, 0, 0.0)?\na) Volledig dekkend (100% zichtbaar).\nb) Zwart.\nc) Volledig transparant (onzichtbaar).\nd) Dit is niet toegelaten.", a: "c) Volledig transparant (onzichtbaar).", o: "4.2 Transparantie & alpha", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 5. Alpha 0 = volledig transparant, 1 = volledig dekkend." },
    { v: "Hoe declareer je een CSS Custom Property (variabele) voor een primaire kleur genaamd 'primary-color'?\na) $primary-color: #0056b3;\nb) --primary-color: #0056b3;\nc) var primary-color = #0056b3;\nd) @primary-color: #0056b3;", a: "b) --primary-color: #0056b3;", o: "4.3 CSS custom properties (variabelen)", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 6. Een variabele begint met twee mintekens: --primary-color." },
    { v: "Hoe pas je een gedeclareerde variabele --primary-color toe op een <h1> in CSS?\na) h1 { color: --primary-color; }\nb) h1 { color: var(--primary-color); }\nc) h1 { color: $primary-color; }\nd) h1 { color: get(--primary-color); }", a: "b) h1 { color: var(--primary-color); }", o: "4.3 CSS custom properties (variabelen)", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 7. Gebruiken doe je met var(): var(--primary-color)." },
    { v: "Gegeven deze CSS:\n  :root { --hoofdkleur: #ff0000; }\n  .kaart { background-color: var(--hoofdkleur); }\nWat gebeurt er als je --hoofdkleur in :root wijzigt naar #008000?\na) Alleen nieuwe elementen krijgen de groene kleur.\nb) Alle elementen die var(--hoofdkleur) gebruiken (zoals .kaart) veranderen automatisch direct naar groen.\nc) Je moet de CSS-code opnieuw compileren met JavaScript.\nd) Er ontstaat een conflict omdat variabelen niet gewijzigd mogen worden.", a: "b) Alle elementen die var(--hoofdkleur) gebruiken (zoals .kaart) veranderen automatisch direct naar groen.", o: "4.3 CSS custom properties (variabelen)", oefening: true,
      uitleg: "Zelftest CSS kleuren, vraag 8. Alles wat var(--hoofdkleur) gebruikt, verandert meteen mee." },
    { v: "Wat is een 'font stack' in de CSS-property font-family?\na) Een verzameling van 10 verschillende lettergrootte-instellingen.\nb) Een door komma's gescheiden lijst van lettertypes waarbij de browser het eerste beschikbare lettertype kiest en anders terugvalt op de volgende.\nc) Een speciale manier om Google Fonts te downloaden via JavaScript.\nd) Een manier om alle bestaande lettertypes in één keer te downloaden.", a: "b) Een door komma's gescheiden lijst van lettertypes waarbij de browser het eerste beschikbare lettertype kiest en anders terugvalt op de volgende.", o: "5.1 Lettertypefamilies", oefening: true,
      uitleg: "Zelftest Typografie, vraag 1. Font stack = lijst met komma's. De browser neemt het eerste lettertype dat hij heeft." },
    { v: "Waarom moet je een font stack in font-family altijd afsluiten met een generieke familienaam (zoals sans-serif, serif of monospace)?\na) Omdat de HTML-validator anders een foutmelding geeft.\nb) Als fallback voor het geval dat geen enkel specifiek opgegeven lettertype aanwezig is op het systeem van de bezoeker.\nc) Om de tekst automatisch vetgedrukt te maken.\nd) Om te zorgen dat de tekst centreert op mobiele schermen.", a: "b) Als fallback voor het geval dat geen enkel specifiek opgegeven lettertype aanwezig is op het systeem van de bezoeker.", o: "5.1 Lettertypefamilies", oefening: true,
      uitleg: "Zelftest Typografie, vraag 2. De generieke familie op het einde is de fallback als geen enkel lettertype aanwezig is." },
    { v: "Wanneer moet je de naam van een lettertype tussen quotes zetten in een font-family declaratie (bijv. \"Courier New\")?\na) Altijd, bij elk lettertype.\nb) Wanneer de naam van het lettertype uit meerdere woorden met spaties bestaat.\nc) Alleen bij generieke familienamen zoals sans-serif.\nd) Alleen bij Google Fonts.", a: "b) Wanneer de naam van het lettertype uit meerdere woorden met spaties bestaat.", o: "5.1 Lettertypefamilies", oefening: true,
      uitleg: "Zelftest Typografie, vraag 3. Quotes als de naam spaties heeft, bv. \"Courier New\"." },
    { v: "Wat is het kenmerk van de maateenheid 'px' (pixel) in CSS?\na) Het is een relatieve eenheid die meeschaalt met de grootte van het ouder-element.\nb) Het is een absolute schermeenheid met een vaste waarde die niet automatisch meeschaalt met de toegankelijkheidsinstellingen (font-size) van de browser.\nc) Het is een relatieve eenheid gebaseerd op de breedte van het scherm.\nd) Het is de standaardeenheid voor het instellen van de regelafstand.", a: "b) Het is een absolute schermeenheid met een vaste waarde die niet automatisch meeschaalt met de toegankelijkheidsinstellingen (font-size) van de browser.", o: "5.2 Lettergrootte & maateenheden", oefening: true,
      uitleg: "Zelftest Typografie, vraag 4. px is absoluut: schaalt niet mee met de lettergrootte die de gebruiker in de browser instelt." },
    { v: "Waarop is de relatieve eenheid 'rem' gebaseerd in CSS?\na) Relatief ten opzichte van de font-size van het directe ouder-element.\nb) Relatief ten opzichte van de font-size van het <html>-rootelement (standaard 1rem = 16px).\nc) Relatief ten opzichte van de breedte van het venster (viewport).\nd) Relatief ten opzichte van de hoogte van de regel.", a: "b) Relatief ten opzichte van de font-size van het <html>-rootelement (standaard 1rem = 16px).", o: "5.2 Lettergrootte & maateenheden", oefening: true,
      uitleg: "Zelftest Typografie, vraag 5. rem = relatief tegenover de font-size van html (standaard 16px)." },
    { v: "Als de standaard root font-size van een pagina 16px is, hoeveel pixels is 2.5rem dan?\na) 25px\nb) 32px\nc) 40px\nd) 250px", a: "c) 40px", o: "5.2 Lettergrootte & maateenheden", oefening: true,
      uitleg: "Zelftest Typografie, vraag 6. 2.5 × 16px = 40px." },
    { v: "Wat is het gevaar van het gebruik van de relatieve eenheid 'em' voor font-size bij diep geneste elementen?\na) em werkt niet op tekst elementen.\nb) em vermenigvuldigt (componeert) zich met de font-size van elk bovenliggend ouder-element, waardoor tekst ongewild steeds groter of kleiner wordt bij nesting.\nc) em maakt de tekst automatisch cursief.\nd) em kan niet gecombineerd worden met kleur.", a: "b) em vermenigvuldigt (componeert) zich met de font-size van elk bovenliggend ouder-element, waardoor tekst ongewild steeds groter of kleiner wordt bij nesting.", o: "5.2 Lettergrootte & maateenheden", oefening: true,
      uitleg: "Zelftest Typografie, vraag 7. em vermenigvuldigt met elke ouder: bij nesting wordt tekst steeds groter of kleiner." },
    { v: "Welke viewport-eenheid komt overeen met exact 1% van de totale breedte van het scherm (browservenster)?\na) 1vh\nb) 1vw\nc) 1rem\nd) 1vpu", a: "b) 1vw", o: "5.2 Lettergrootte & maateenheden", oefening: true,
      uitleg: "Zelftest Typografie, vraag 8. 1vw = 1% van de breedte van het venster. (1vh = 1% van de hoogte.)" },
    { v: "Hoe verwijder je de standaard onderlijning van hyperlinks (<a>-elementen) in CSS?\na) a { text-style: none; }\nb) a { text-decoration: none; }\nc) a { font-style: no-underline; }\nd) a { text-line: off; }", a: "b) a { text-decoration: none; }", o: "5.3 Tekststijlen & opmaak", oefening: true,
      uitleg: "Zelftest Typografie, vraag 9. text-decoration: none; haalt de onderlijning weg." },
    { v: "Waarom is een waarde zonder eenheid, zoals line-height: 1.6 de best practice voor de regelafstand van teksten?\na) Omdat de regelafstand zich zo proportioneel aanpast aan de font-size van het element en geërfde elementen, zonder vaste pixel-overlappingen te veroorzaken.\nb) Omdat browsers geen pixels accepteren bij line-height.\nc) Omdat 1.6 automatisch de tekst centreert.\nd) Omdat het verplicht is volgens de HTML5-standaard.", a: "a) Omdat de regelafstand zich zo proportioneel aanpast aan de font-size van het element en geërfde elementen, zonder vaste pixel-overlappingen te veroorzaken.", o: "5.3 Tekststijlen & opmaak", oefening: true,
      uitleg: "Zelftest Typografie, vraag 10. Zonder eenheid schaalt de regelafstand mee met de font-size, ook bij kind-elementen." },
  ],
};
